void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    vec2 uv = (fragCoord / iResolution.xy);

    vec3 color = texture(iChannel0, uv).rgb;
    vec3 bloom1 = textureLod(iChannel0, uv, 4.5).rgb;
    vec3 bloom2 = textureLod(iChannel0, uv, 5.5).rgb;

    // color = vec3(0.0);
    color += 0.15 * smoothstep(0.2, 2.5, bloom1.r + bloom1.g + bloom1.b);
    color += 0.15 * smoothstep(0.2, 2.5, bloom2.r + bloom2.g + bloom2.b);

    color += (hash13(vec3(fragCoord, iTime)) - 0.5) / 16.0;

    fragColor = vec4(color, 1.0);
}

#define TAU 6.28318530718

#define DER_PREC   1.0 / 256.0

#define DIST_STEPS 4
#define DIST_ROT   0.150
#define DIST_AMP   0.200
#define DIST_SPD   0.250

#define SUN_DIR    vec3(0.0, 0.5, 1.0)
#define AMP        1.9

float hash13(vec3 p3) {
	p3  = fract(p3 * 0.1031);
    p3 += dot(p3, p3.zyx + 31.32);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 rotateUv(vec2 uv, float a) {

    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, s, -s, c);
    return m * uv;

}

float sampleHeight(vec2 uv) {

    float hill = smoothstep(2.0, 0.0, length(uv));

    float diag = dot(uv, vec2(10.0, 90.0));
    float detail = sin(diag);
    hill += detail / 2500.0;

    return hill;

}

vec2 distortUv(vec2 uv, float time) {

    // Main wave + rotate distortion
    for (int i = 0; i < DIST_STEPS; i ++) {

        uv.x += cos((uv.y + time * DIST_SPD) * TAU) * DIST_AMP;
        uv = rotateUv(uv, DIST_ROT * TAU);

    }

    return uv;

}

vec3 effect(vec2 uv, float time) {

    // Derivative offset
    float off = DER_PREC;

    // Scale derivative offset (form circle)
    off = mix(off, 1.0, smoothstep(0.44, 0.5, length(uv)));

    // Scale
    uv *= 1.8;

    // Distort self and derivatives' UV
    vec2 distUv   = distortUv(uv                 , time / 10.0);
    vec2 distUv10 = distortUv(uv + vec2(off, 0.0), time / 10.0);
    vec2 distUv01 = distortUv(uv + vec2(0.0, off), time / 10.0);

    // Sample height for self and derivatives
    float height   = sampleHeight(distUv  );
    float height10 = sampleHeight(distUv10);
    float height01 = sampleHeight(distUv01);

    // Calculate normal accordingly
    vec3 der10 = vec3(off, 0.0, height10 - height);
    vec3 der01 = vec3(0.0, off, height01 - height);
    vec3 normal = normalize(cross(der10, der01));

    vec3 color;

    // Get sun direction
    vec3 sunDir = normalize(SUN_DIR);
    float sunDot = max(0.0, dot(sunDir, normal));

    // Albedo and highlight
    color += pow(sunDot,  2.5) * height * 0.08;
    color += pow(sunDot, 48.0) * height * 0.40;

    // Fresnel
    vec3 fresCol = vec3(0.5, 0.1, 0.2);
    float fresDot = dot(vec3(0.0, 0.0, 1.0), normal);
    color += fresCol * pow(1.0 - fresDot, 3.0);

    return color * AMP;

}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    float uvSize = min(iResolution.x, iResolution.y);
    vec2 uv = (fragCoord - iResolution.xy / 2.0) / uvSize;

    vec3 color = effect(uv, iTime);

    fragColor = vec4(color, 1.0);
}
